#!/usr/bin/env python3
##
# @file tractor_trailer_adapters.py
#
# @brief Reusable controller wrappers for tracking tractor-trailer
# trajectories generated by BSplineTractorTrailerCoverage /
# BSplineEnergyTractorTrailerCoverage with a tractor-pose controller such as
# PurePursuit.
#
# Only the tractor is actuated; the hitch angle gamma is a PASSIVE state
# (gammadot = thetadot_trailer - w_tractor). A tractor-pose controller alone
# never observes or targets gamma, so tracking-time disturbance can let it
# drift toward the mechanical jackknife limit even while tractor
# position/heading track well. These two wrappers close that loop:
#
#   TrailerToTractorPoseAdapter: derives the tractor's own pose from the
#       plant's true trailer-frame state via forward kinematics, so an inner
#       controller can track a tractor-frame reference (a differentially
#       driven tractor is a unicycle in its own right, so the inner
#       controller's raw [v, w] output drives the tractor input unmodified).
#
#   HitchStabilizedController: adds an explicit proportional correction to
#       the commanded w, pulling the measured hitch angle toward its
#       trajectory-generator-planned reference, layered additively on top of
#       (not replacing) the tractor-pose-tracking command.
#
# Generalized from the validated pattern in
# examples/export_section5_tractor_trailer.py (_TrailerToTractorPoseAdapter,
# _HitchStabilizedController), which found that tracking the trailer's pose
# directly (rather than the tractor's) lets gamma wander to an unstable
# ~180 deg equilibrium, and that omitting hitch feedback entirely let gamma
# drift to 82-86 deg against a 44.98 deg mechanical limit.
#
# @section author_doxygen_example Author(s)
# - Created by Tran Viet Thanh on 2026/08/12

# Standard library
import numpy as np


class TrailerToTractorPoseAdapter:
    """! Forward-kinematics wrapper: tracks a tractor-frame reference using
    an inner controller, while the plant's true state is trailer-frame.
    """

    def __init__(self, controller, length_back, length_front):
        """! Constructor.
        @param controller<instance>: Inner tractor-pose-tracking controller
            (e.g. PurePursuit), constructed against a tractor-frame
            Trajectory.
        @param length_back<float>: lb -- tractor rear axle to hitch [m].
        @param length_front<float>: lf -- hitch to trailer rear axle [m].
        """
        self._controller = controller

        self.length_back = length_back

        self.length_front = length_front

    def initialize(self):
        """! Initialize the inner controller."""
        self._controller.initialize()

    def execute(self, state, input, index):
        """! Derive the tractor pose from the true articulated state and
        delegate to the inner controller.
        @param state<list>: True plant state [x, y, theta, gamma]
            (trailer-frame).
        @param input<list>: Previous control input.
        @param index<int>: Previous trajectory index.
        @return<tuple>: (status, [v_tractor, w_tractor]) from the inner
            controller, unmodified.
        """
        x, y, theta, gamma = state[0], state[1], state[2], state[3]

        xt = x + self.length_front * np.cos(theta) + \
            self.length_back * np.cos(theta - gamma)

        yt = y + self.length_front * np.sin(theta) + \
            self.length_back * np.sin(theta - gamma)

        thetat = theta - gamma

        return self._controller.execute(
            np.array([xt, yt, thetat]), input, index)


class HitchStabilizedController:
    """! Adds explicit hitch-angle feedback on top of an existing
    tractor-pose-tracking controller.

    Sign derivation: the plant ODE gives gamma_dot = theta_dot_trailer -
    w_tractor, so INCREASING w_tractor DECREASES gamma_dot. If
    gamma_meas > gamma_ref (hitch angle too large), gamma_dot should be
    driven negative, so w_tractor must INCREASE:
        correction = +k_gamma * (gamma_meas - gamma_ref),  k_gamma > 0.
    """

    def __init__(self, controller, gamma_ref, k_gamma, gamma_std=0.0,
                max_correction=1.0, rng=None):
        """! Constructor.
        @param controller<instance>: Inner controller to wrap (e.g. a
            TrailerToTractorPoseAdapter around PurePursuit). Must return
            (status, [v_tractor, w_tractor]) from execute().
        @param gamma_ref<array>: Trajectory-generator-planned hitch angle
            [rad], one value per control step (same time grid/index as the
            trajectory the inner controller tracks).
        @param k_gamma<float>: Proportional gain [1/s] on the hitch angle
            error, added to the commanded w_tractor.
        @param gamma_std<float>: Standard deviation [rad] of synthetic noise
            added to state[3] before use, to model imperfect hitch sensing
            in simulation. Default 0.0 -- consumes state[3] directly, which
            is the appropriate default when state[3] already IS the measured
            (not ground-truth) hitch angle, as on real hardware fed by an
            IMU/rotary encoder.
        @param max_correction<float>: Clamp [rad/s] on the correction
            magnitude.
        @param rng<numpy.random.Generator|None>: RNG for the synthetic noise
            (only used when gamma_std > 0). Defaults to a fresh Generator.
        """
        self._controller = controller

        self._gamma_ref = np.asarray(gamma_ref)

        self._k_gamma = float(k_gamma)

        self._gamma_std = float(gamma_std)

        self._max_correction = float(max_correction)

        self._rng = rng if rng is not None else np.random.default_rng()

    def initialize(self):
        """! Initialize the inner controller."""
        self._controller.initialize()

    def execute(self, state, input, index):
        """! Compute the inner controller's command and add the hitch
        correction.
        @param state<list>: True plant state [x, y, theta, gamma].
        @param input<list>: Previous control input.
        @param index<int>: Current trajectory index, used to look up
            gamma_ref.
        @return<tuple>: (status, [v_tractor, w_tractor + correction]).
        """
        status, uv = self._controller.execute(state, input, index)

        if not status:
            return status, uv

        gamma_true = float(state[3])

        if self._gamma_std > 0.0:
            gamma_meas = gamma_true + self._rng.normal(0.0, self._gamma_std)
        else:
            gamma_meas = gamma_true

        gamma_ref_t = float(
            self._gamma_ref[min(index, len(self._gamma_ref) - 1)])

        correction = self._k_gamma * (gamma_meas - gamma_ref_t)

        correction = float(
            np.clip(correction, -self._max_correction, self._max_correction))

        v_trac, w_trac = float(uv[0]), float(uv[1])

        return status, [v_trac, w_trac + correction]
